import re
from pathlib import Path

import pytest

REPO = Path(__file__).resolve().parent.parent
DRIVERS = REPO / "drivers" / "virtio"
CONFIG_H = REPO / "include" / "uapi" / "linux" / "virtio_config.h"
MECH_CASES = REPO / "quality" / "mechanical" / "vring_transport_features_cases.txt"


# --------------------------------------------------------------------------- #
# Helpers — read source, slice function bodies, never copy from artifacts      #
# --------------------------------------------------------------------------- #

def _read(path: Path) -> str:
    return path.read_text(encoding="utf-8", errors="ignore")


def _func_body(source: str, signature_regex: str) -> str:
    """Return the text of a C function body from its signature to the first
    line that is a lone closing brace at column 0. Mirrors the awk
    `/sig/,/^}$/` slice used by quality/mechanical/verify.py."""
    lines = source.splitlines()
    start = None
    for i, line in enumerate(lines):
        if re.search(signature_regex, line):
            start = i
            break
    assert start is not None, f"signature not found: {signature_regex}"
    body = [lines[start]]
    for line in lines[start + 1:]:
        body.append(line)
        if line == "}":
            break
    return "\n".join(body)


def _case_labels(func_body: str) -> set:
    labels = set()
    for line in func_body.splitlines():
        s = line.strip()
        if s.startswith("case ") and s.endswith(":"):
            labels.add(s[len("case "):-1].strip())
    return labels


def _header_transport_bits() -> dict:
    """name -> int value, for #defines with value in [28, 42)."""
    bits = {}
    for line in _read(CONFIG_H).splitlines():
        m = re.match(r"#define\s+(VIRTIO_(?:RING_)?F_[A-Z0-9_]+)\s+(\d+)", line)
        if m:
            name, val = m.group(1), int(m.group(2))
            if 28 <= val < 42:
                bits[name] = val
    return bits


