class TestSpecRequirements:
    """One test per testable requirement from quality/REQUIREMENTS.md."""

    def test_req002_whitelist_clears_unenumerated_via_default(self):
        """[Req: inferred — REQ-002] vring_transport_features clears any
        transport bit not enumerated, via __virtio_clear_bit in default:."""
        body = _func_body(_read(DRIVERS / "virtio_ring.c"),
                          r"void\s+vring_transport_features")
        assert "default:" in body, "whitelist must have a default branch"
        assert "__virtio_clear_bit" in body, \
            "default branch must clear unenumerated bits"

    def test_req002_case_set_is_exactly_the_known_eight(self):
        """[Req: inferred — REQ-002] The closed set is the 8 enumerated bits;
        extracted FROM SOURCE, not from REQUIREMENTS.md."""
        body = _func_body(_read(DRIVERS / "virtio_ring.c"),
                          r"void\s+vring_transport_features")
        labels = _case_labels(body)
        expected = {
            "VIRTIO_RING_F_INDIRECT_DESC", "VIRTIO_RING_F_EVENT_IDX",
            "VIRTIO_F_VERSION_1", "VIRTIO_F_ACCESS_PLATFORM",
            "VIRTIO_F_RING_PACKED", "VIRTIO_F_ORDER_PLATFORM",
            "VIRTIO_F_NOTIFICATION_DATA", "VIRTIO_F_IN_ORDER",
        }
        assert labels == expected, f"case set drifted: {labels ^ expected}"

    def test_req001_core_preserve_loop_readds_transport_bits(self):
        """[Req: inferred — REQ-001] The core re-adds every device-offered
        transport bit before calling per-transport finalize."""
        src = _read(DRIVERS / "virtio.c")
        assert "VIRTIO_TRANSPORT_F_START" in src and "VIRTIO_TRANSPORT_F_END" in src
        assert "__virtio_set_bit" in src, \
            "core must set (preserve) transport bits before finalize"
        assert "finalize_features" in src

    def test_req003_pci_modern_reset_polls_for_status_zero(self):
        """[Req: Tier-4 — REQ-003] PCI-modern vp_reset polls until status==0."""
        body = _func_body(_read(DRIVERS / "virtio_pci_modern.c"),
                          r"\bvp_reset\b")
        assert "while" in body and "get_status" in body, \
            "vp_reset must poll status (the spec §5 reference impl)"

    def test_req004_mmio_interrupt_sets_handled_on_config(self):
        """[Req: inferred — REQ-004] MMIO vm_interrupt returns IRQ_HANDLED on
        config — the conformant reference."""
        body = _func_body(_read(DRIVERS / "virtio_mmio.c"), r"\bvm_interrupt\b")
        assert "IRQ_HANDLED" in body
        assert "INT_CONFIG" in body or "VIRTIO_MMIO_INT_CONFIG" in body

    def test_req006_features_ok_rechecks_for_version_1(self):
        """[Req: Tier-4 — REQ-006] virtio_features_ok sets and re-reads
        FEATURES_OK for modern devices, early-returns for legacy."""
        body = _func_body(_read(DRIVERS / "virtio.c"), r"virtio_features_ok")
        assert "VIRTIO_CONFIG_S_FEATURES_OK" in body
        assert "VIRTIO_F_VERSION_1" in body, \
            "legacy early-return must gate on VERSION_1"

    def test_req008_ring_has_write_barriers(self):
        """[Req: Tier-4 — REQ-008] The ring uses write barriers between
        descriptor writes and index updates."""
        src = _read(DRIVERS / "virtio_ring.c")
        assert "virtio_wmb" in src, "ring must issue write barriers"

    def test_req002_mechanical_receipt_exists_and_lists_eight_cases(self):
        """[Req: inferred — REQ-002 / REQ-016] The mechanical extraction
        receipt exists and is the authoritative code-side list."""
        assert MECH_CASES.is_file(), \
            "quality/mechanical/vring_transport_features_cases.txt must exist"
        receipt_labels = _case_labels(_read(MECH_CASES))
        assert len(receipt_labels) == 8, \
            f"receipt should list 8 case labels, got {len(receipt_labels)}"


