class TestFitnessScenarios:
    """One test per QUALITY.md fitness-to-purpose scenario, named to match."""

    def test_scenario_1_mmio_finalize_preserves_ring_reset(self):
        """[Req: inferred — QUALITY.md Scenario 1] MMIO vm_finalize_features
        should re-add RING_RESET after vring_transport_features clears it.

        This asserts the DESIRED behavior; it is expected to FAIL on current
        source (the bug), so it is a candidate-bug detector. Marked xfail."""
        body = _func_body(_read(DRIVERS / "virtio_mmio.c"),
                          r"\bvm_finalize_features\b")
        assert "vring_transport_features" in body
        # Desired: a re-add of RING_RESET after the whitelist call.
        post = body.split("vring_transport_features", 1)[1]
        if "VIRTIO_F_RING_RESET" not in post:
            pytest.xfail("BUG candidate: vm_finalize_features does not "
                         "re-preserve RING_RESET (REQ-001)")
        assert "VIRTIO_F_RING_RESET" in post

    def test_scenario_2_notif_config_data_preserved_if_validated(self):
        """[Req: inferred — QUALITY.md Scenario 2] If vp_check_common_size
        validates NOTIF_CONFIG_DATA, vp_transport_features must re-add bit 39."""
        src = _read(DRIVERS / "virtio_pci_modern.c")
        check_body = _func_body(src, r"\bvp_check_common_size\b")
        trans_body = _func_body(src, r"\bvp_transport_features\b")
        if "VIRTIO_F_NOTIF_CONFIG_DATA" in check_body:
            if "VIRTIO_F_NOTIF_CONFIG_DATA" not in trans_body:
                pytest.xfail("BUG candidate: NOTIF_CONFIG_DATA validated by "
                             "vp_check_common_size but never re-added by "
                             "vp_transport_features (REQ-005)")
            assert "VIRTIO_F_NOTIF_CONFIG_DATA" in trans_body

    def test_scenario_3_mmio_reset_waits_for_status_zero(self):
        """[Req: Tier-4 — QUALITY.md Scenario 3] vm_reset must poll status
        until it reads 0 (spec §5)."""
        body = _func_body(_read(DRIVERS / "virtio_mmio.c"), r"\bvm_reset\b")
        has_poll = "while" in body and ("STATUS" in body or "readl" in body)
        if not has_poll:
            pytest.xfail("BUG candidate: vm_reset has no status poll loop "
                         "(REQ-003 / spec §5)")
        assert has_poll

    def test_scenario_4_pci_config_interrupt_returns_handled(self):
        """[Req: inferred — QUALITY.md Scenario 4] vp_interrupt must propagate
        IRQ_HANDLED from the config-change branch."""
        body = _func_body(_read(DRIVERS / "virtio_pci_common.c"),
                          r"\bvp_interrupt\b")
        assert "vp_config_changed" in body
        # Desired: the config branch's IRQ_HANDLED is captured or returned,
        # not discarded as a bare call statement.
        captures = bool(re.search(r"=\s*vp_config_changed", body)) \
            or bool(re.search(r"ret\s*\|?=.*IRQ_HANDLED", body))
        bare_call = bool(re.search(r"^\s*vp_config_changed\s*\(", body, re.M))
        if bare_call and not captures:
            pytest.xfail("BUG candidate: vp_interrupt discards "
                         "vp_config_changed's IRQ_HANDLED return (REQ-004)")
        assert captures

    def test_scenario_5_vdpa_finalize_preserves_ring_reset(self):
        """[Req: inferred — QUALITY.md Scenario 5] vDPA finalize should
        re-preserve RING_RESET before vdpa_set_features."""
        body = _func_body(_read(DRIVERS / "virtio_vdpa.c"),
                          r"virtio_vdpa_finalize_features")
        assert "vring_transport_features" in body
        post = body.split("vring_transport_features", 1)[1]
        if "VIRTIO_F_RING_RESET" not in post:
            pytest.xfail("BUG candidate: virtio_vdpa_finalize_features does "
                         "not re-preserve RING_RESET (REQ-001)")
        assert "VIRTIO_F_RING_RESET" in post

    def test_scenario_6_whitelist_enumeration_matches_known_gap(self):
        """[Req: inferred — QUALITY.md Scenario 6] The diff between header
        transport bits and case labels is exactly the known {37,39,40,41}
        compensation set — a new entry means a bit was added to the header
        without updating the switch."""
        body = _func_body(_read(DRIVERS / "virtio_ring.c"),
                          r"void\s+vring_transport_features")
        labels = _case_labels(body)
        header = _header_transport_bits()
        missing = {v for n, v in header.items() if n not in labels}
        # Bits 28/29 are RING_F_* whose #defines live in another header, but
        # their case labels ARE present, so they never appear as missing.
        assert missing == {37, 39, 40, 41}, \
            f"whitelist gap changed from the known set: {missing}"

    def test_scenario_7_packed_wrap_toggles_counter_and_flags(self):
        """[Req: inferred — QUALITY.md Scenario 7] The packed wrap site mutates
        both the wrap counter and the avail/used flags."""
        src = _read(DRIVERS / "virtio_ring.c")
        assert "avail_wrap_counter" in src
        assert "avail_used_flags" in src

    def test_scenario_8_legacy_reset_divergence_documented(self):
        """[Req: Tier-4 — QUALITY.md Scenario 8] The legacy reset single-read
        divergence is documented as intentional (in REQUIREMENTS.md REQ-003
        cond 4), distinguishing it from the MMIO accidental omission."""
        reqs = _read(REPO / "quality" / "REQUIREMENTS.md")
        assert "PCI-legacy" in reqs and "intentional" in reqs.lower(), \
            "legacy reset exemption must be documented in REQUIREMENTS.md"


