class TestBoundariesAndEdgeCases:
    """One test per defensive/boundary pattern from the negotiation surface."""

    def test_legacy_finalize_is_32bit_bounded(self):
        """[Req: inferred — from vp_finalize_features(legacy) BUG_ON guard]
        Legacy finalize guards against >32-bit features (bits 37-41 out of
        range), which is why it is exempt from the compensation requirement."""
        body = _func_body(_read(DRIVERS / "virtio_pci_legacy.c"),
                          r"\bvp_finalize_features\b")
        assert "BUG_ON" in body or "vring_transport_features" in body

    def test_transport_range_boundaries_are_28_and_42(self):
        """[Req: inferred — from VIRTIO_TRANSPORT_F_START/END] The transport
        range boundaries are the values the whitelist loop iterates over."""
        src = _read(CONFIG_H)
        assert re.search(r"#define\s+VIRTIO_TRANSPORT_F_START\s+28", src)
        assert re.search(r"#define\s+VIRTIO_TRANSPORT_F_END\s+42", src)

    def test_features_ok_legacy_returns_before_setting_features_ok(self):
        """[Req: inferred — from virtio_features_ok legacy early-return] The
        legacy branch returns 0 BEFORE FEATURES_OK is set (no acceptance
        confirmation by design)."""
        body = _func_body(_read(DRIVERS / "virtio.c"), r"virtio_features_ok")
        idx_version = body.find("VIRTIO_F_VERSION_1")
        idx_features_ok = body.find("VIRTIO_CONFIG_S_FEATURES_OK")
        assert idx_version != -1 and idx_features_ok != -1
        assert idx_version < idx_features_ok, \
            "VERSION_1 gate must precede the FEATURES_OK set/recheck"

    def test_zero_isr_returns_irq_none(self):
        """[Req: inferred — from vp_interrupt isr==0 guard] A zero ISR returns
        IRQ_NONE (correct spurious-interrupt rejection)."""
        body = _func_body(_read(DRIVERS / "virtio_pci_common.c"),
                          r"\bvp_interrupt\b")
        assert "IRQ_NONE" in body, "vp_interrupt must reject a zero ISR"

    def test_vdpa_reset_delegates_to_backend(self):
        """[Req: inferred — from virtio_vdpa_reset delegation] vDPA reset
        delegates the wait to the backend; guest reinit must not assume sync."""
        body = _func_body(_read(DRIVERS / "virtio_vdpa.c"),
                          r"virtio_vdpa_reset")
        assert "vdpa" in body.lower()

    def test_mmio_finalize_writes_driver_features_register(self):
        """[Req: inferred — from vm_finalize_features register write] MMIO
        finalize writes negotiated features to the DRIVER_FEATURES register —
        the write that publishes whatever survived the whitelist."""
        body = _func_body(_read(DRIVERS / "virtio_mmio.c"),
                          r"\bvm_finalize_features\b")
        assert "DRIVER_FEATURES" in body or "writel" in body

    def test_pci_modern_compensator_readds_three_bits(self):
        """[Req: inferred — from vp_transport_features re-add set] The modern
        compensator re-adds SR_IOV/RING_RESET/ADMIN_VQ — boundary check that it
        covers 37/40/41 (and the bit-39 gap is real)."""
        body = _func_body(_read(DRIVERS / "virtio_pci_modern.c"),
                          r"\bvp_transport_features\b")
        for bit in ("VIRTIO_F_SR_IOV", "VIRTIO_F_RING_RESET", "VIRTIO_F_ADMIN_VQ"):
            assert bit in body, f"compensator should re-add {bit}"


